def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append((oid, opp))

    if not alive_opponents:
        safe_bid = DAILY_SALARY * 0.35
        if no_water_days >= 2 or hp <= 3:
            safe_bid = DAILY_SALARY * 0.75
        return float(min(budget, safe_bid))

    prev_bids = []
    prev_high = 0.0
    prev_eric = None
    desperate_count = 0
    rich_count = 0

    for oid, opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) > prev_high:
                prev_high = float(bid)
            if oid == 'Eric':
                prev_eric = float(bid)
        if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 3:
            desperate_count += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            rich_count += 1

    target_pressure = prev_high
    if prev_eric is not None:
        target_pressure = max(target_pressure, prev_eric)

    units = supply / float(WATER_REQ)
    tight_supply = units <= 1.35
    medium_supply = units <= 1.7

    urgency = 0
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days == 1:
        urgency += 1
    if hp <= 3:
        urgency += 3
    elif hp <= 6:
        urgency += 1
    if tight_supply:
        urgency += 2
    elif medium_supply:
        urgency += 1
    if desperate_count >= 2:
        urgency += 1
    if day >= 8:
        urgency += 1

    if target_pressure <= 0:
        if urgency >= 5:
            bid = DAILY_SALARY * 0.9
        elif urgency >= 3:
            bid = DAILY_SALARY * 0.65
        else:
            bid = DAILY_SALARY * 0.4
        return float(min(budget, bid))

    if urgency >= 6:
        bid = max(DAILY_SALARY * 0.95, target_pressure + 3.0)
    elif urgency >= 4:
        bid = max(DAILY_SALARY * 0.78, target_pressure + 1.5)
    elif urgency >= 2:
        if target_pressure >= DAILY_SALARY * 1.5:
            bid = DAILY_SALARY * 0.52
        else:
            bid = max(DAILY_SALARY * 0.55, target_pressure * 0.78)
    else:
        if not tight_supply and rich_count <= 1 and target_pressure >= DAILY_SALARY * 1.2:
            bid = DAILY_SALARY * 0.32
        else:
            bid = max(DAILY_SALARY * 0.42, target_pressure * 0.62)

    if budget < DAILY_SALARY * 0.6 and urgency < 4:
        bid = min(bid, budget * 0.7)

    if no_water_days >= 2 or hp <= 2:
        bid = max(bid, DAILY_SALARY * 0.95)

    return float(min(budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Immediate reaction from yesterday's bid (only previous_trace)
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many units water might be available (heuristic)
    # Use int() to avoid float indices issues (even though we don't index lists here).
    approx_units = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0
    if approx_units < 1:
        approx_units = 1

    # Base bid level: aim between Eric-like pressure and Alex-like restraint.
    # If opponent previously went very high, we slightly undercut to avoid overpaying.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # High-stakes day: bid moderately if healthy, aggressively if low hp.
        if my_hp > 3.0 and my_no_water_days <= 1:
            target = DAILY_SALARY * 0.35
        else:
            target = DAILY_SALARY * 0.75
    else:
        # Lower pressure: bid enough to secure, but avoid wasting budget.
        if my_hp <= 2.0 or my_no_water_days >= 2:
            target = DAILY_SALARY * 0.8
        else:
            # Scale with supply: if supply is scarce relative to requirement, bid more.
            scarcity = (float(MAX_SUPPLY) - supply) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
            target = DAILY_SALARY * (0.48 + 0.22 * scarcity)

    # Undercut vs previous highest bid to win at lower cost.
    # Keep it bounded and not too low.
    if highest_prev_bid > 0.0:
        target = min(target, highest_prev_bid - 1.0)
        # If undercut becomes too small, clamp to a reasonable floor.
        floor_bid = DAILY_SALARY * 0.28
        if target < floor_bid:
            target = floor_bid

    # Convert to final bid with safety caps.
    # Never bid more than budget.
    bid = max(0.0, min(my_budget, float(target)))

    # If we are in danger, ensure we bid closer to salary.
    if my_hp <= 1.5 or my_no_water_days >= 3:
        bid = max(bid, min(my_budget, DAILY_SALARY * 0.92))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    bid_value = DAILY_SALARY * 0.5 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return max(1, min(my_status['budget'], DAILY_SALARY * 0.1))

    if my_status['hp'] <= 2:
        bid_value = DAILY_SALARY * 0.98 
    elif my_status['hp'] <= 4:
        bid_value = DAILY_SALARY * 0.85 
    elif my_status['no_water_days'] > 0:
        bid_value = DAILY_SALARY * 0.75 
    else:
        bid_value = DAILY_SALARY * 0.6 

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] <= 4 or my_status['no_water_days'] > 0:
                bid_value = max(bid_value, highest_prev_bid + 5)
            else:
                bid_value = max(bid_value, highest_prev_bid + 1)
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            bid_value = max(bid_value, highest_prev_bid + 1)
        elif highest_prev_bid < DAILY_SALARY * 0.3 and my_status['hp'] > 5 and my_status['no_water_days'] == 0:
            bid_value = min(bid_value, DAILY_SALARY * 0.4)

    current_supply = day_context['supply']
    num_possible_winners = int(current_supply // WATER_REQ)

    if num_possible_winners == 1:
        if num_alive_opponents >= 1:
            if my_status['hp'] <= 6 or my_status['no_water_days'] > 0:
                bid_value *= 1.15 
            else:
                bid_value *= 1.05 
    elif num_possible_winners >= 2:
        if my_status['hp'] > 5 and my_status['no_water_days'] == 0:
            bid_value *= 0.9
        else:
            bid_value *= 1.05 

    current_day = day_context['day']
    remaining_days = EPISODE_DAYS - current_day

    if remaining_days <= 3 and my_status['hp'] > 0:
        if my_status['hp'] <= 4 or my_status['no_water_days'] > 0:
            bid_value = max(bid_value, DAILY_SALARY * 0.9) 
        else:
            bid_value = max(bid_value, DAILY_SALARY * 0.7) 

    final_bid = min(my_status['budget'], bid_value)

    return max(1, int(final_bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = {aid: o for aid, o in opponents_status.items() if o['alive']}

    # Get yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine target bid based on yesterday's maximum
    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)
        # Base bid is slightly above yesterday's max, but scaled by supply vs requirement
        if supply < WATER_REQ:
            # critical: need water desperately
            bid = min(budget, max_yesterday_bid + 1.5)
        else:
            # enough supply: bid moderately above if we need water, else conserve
            if hp < 3:
                bid = min(budget, max_yesterday_bid + 1.5)
            elif hp <= 5:
                bid = min(budget, max_yesterday_bid * 0.9)
            else:
                bid = min(budget, max_yesterday_bid * 0.5)
    else:
        # No historical data: use need-based
        if hp < 3 or no_water_days > 0:
            bid = min(budget, DAILY_SALARY * 0.85)
        else:
            bid = min(budget, DAILY_SALARY * 0.6)

    # Ensure bid is affordable and non-negative
    bid = max(0, min(bid, budget))
    # If we have no budget, can't bid
    if budget <= 0:
        return 0
    return int(bid)
